class MusicaAmbienteB41(QObject):
    """Reproduz uma trilha em loop fora da bateria e oferece um botão na Home."""

    NOME_ARQUIVO = "menu_saltitante_b41.wav"
    CHAVE = "musica_ambiente_ativa"

    def __init__(self, janela, home, cartoon):
        super().__init__(janela)
        self._janela = janela
        self._home = home
        self._cartoon = cartoon
        self._app = QApplication.instance()
        self._preferencias = QSettings("VighnaStudy", "MusicaAmbienteB41")
        valor = str(self._preferencias.value(self.CHAVE, True)).strip().lower()
        self.habilitada = valor not in ("false", "0", "no", "off", "")
        base = Path(os.environ.get("LOCALAPPDATA") or tempfile.gettempdir())
        self._arquivo = base / "VighnaStudy" / "Cache" / "musica_b41" / self.NOME_ARQUIVO
        self._efeito = None
        self._backend = None
        self._alias = "vighna_menu_b41"
        self._mci_aberto = False
        self._mci_pausado = False
        self._em_execucao = False
        self._falha = False
        self._avisou_falha = False
        self._encerrado = False
        self._iniciado = False

        self._repetir = QTimer(self)
        self._repetir.setInterval(450)
        self._repetir.timeout.connect(self._checar_loop_mci)
        self._botao_cartoon = self._criar_botao(cartoon, cartoon=True)
        self._botao_normal = self._criar_botao(home, cartoon=False)
        self._home.installEventFilter(self)
        self._cartoon.installEventFilter(self)
        if self._app is not None:
            self._app.installEventFilter(self)
            self._app.aboutToQuit.connect(self.finalizar)
        self.sincronizar_controles()

    def _criar_botao(self, pai, cartoon=False):
        botao = QPushButton(pai)
        botao.setObjectName("b41MusicCartoonToggle" if cartoon else "b41MusicOriginalToggle")
        botao.setCursor(Qt.PointingHandCursor)
        botao.setFocusPolicy(Qt.StrongFocus)
        botao.setAccessibleName("Ativar ou desativar a música ambiente do VighnaStudy")
        if cartoon:
            botao.setStyleSheet(
                "QPushButton {color:#ffffff;background:rgba(16,51,82,0.92);"
                "border:1px solid #92cee2;border-radius:9px;padding:4px 8px;"
                "font-size:10pt;font-weight:650;}"
                "QPushButton:hover {background:#235b7c;border-color:#ffd38a;}"
                "QPushButton:focus {border:2px solid #ffd38a;}"
            )
        else:
            botao.setStyleSheet(
                "QPushButton {color:#eaf8ff;background:#0e3048;"
                "border:1px solid #3db9d3;border-radius:9px;padding:5px 10px;"
                "font-size:10pt;font-weight:600;}"
                "QPushButton:hover {background:#19506a;border-color:#ffd38a;}"
                "QPushButton:focus {border:2px solid #ffd38a;}"
            )
        botao.clicked.connect(lambda _checked=False: self.alternar())
        return botao

    def _posicionar(self):
        escala, dx, dy = self._cartoon._geometry()
        self._botao_cartoon.setGeometry(
            round(dx + 950 * escala), round(dy + 668 * escala),
            max(125, round(190 * escala)), max(27, round(32 * escala)),
        )
        self._botao_normal.setGeometry(
            max(10, self._home.width() - 213),
            max(10, self._home.height() - 53), 188, 35,
        )

    def _ha_bateria_aberta(self):
        # A bateria e um QDialog top-level nao-modal (inclui simulado e treino).
        if self._app is None:
            return False
        for janela in self._app.topLevelWidgets():
            if type(janela).__name__ != "JanelaResolverQuestoes":
                continue
            try:
                if janela.isVisible() or janela.isMinimized():
                    return True
            except RuntimeError:
                pass
        return False

    def _pode_tocar(self):
        return (self._iniciado and not self._encerrado and not self._falha
                and self.habilitada and not self._ha_bateria_aberta())

    def iniciar(self):
        if self._encerrado:
            return
        self._iniciado = True
        self.sincronizar()

    def alternar(self):
        self.habilitada = not self.habilitada
        self._preferencias.setValue(self.CHAVE, self.habilitada)
        self._preferencias.sync()
        self.sincronizar()
        return self.habilitada

    def sincronizar_controles(self):
        self._posicionar()
        inicio = self._janela.telas.currentWidget() is self._home
        cartoon = bool(self._cartoon.cartoon_enabled)
        self._botao_cartoon.setVisible(inicio and cartoon)
        self._botao_normal.setVisible(inicio and not cartoon)
        nome = "♫ Música ligada" if self.habilitada else "♪ Música desligada"
        detalhe = ("Clique para silenciar a trilha Menu Saltitante."
                   if self.habilitada else "Clique para ligar a trilha Menu Saltitante.")
        for botao in (self._botao_cartoon, self._botao_normal):
            botao.setText(nome)
            botao.setToolTip(detalhe + " Não toca na Bateria de Questões.")
        if inicio:
            (self._botao_cartoon if cartoon else self._botao_normal).raise_()

    def sincronizar(self, *_args):
        if self._encerrado:
            return
        self.sincronizar_controles()
        if self._pode_tocar():
            self._reproduzir()
        else:
            self._pausar()

    def eventFilter(self, objeto, evento):
        try:
            tipo = evento.type()
            if objeto is self._home and tipo in (QEvent.Resize, QEvent.Show):
                self._posicionar()
            elif objeto is self._cartoon and tipo in (QEvent.Resize, QEvent.Show):
                self._posicionar()
            elif (type(objeto).__name__ == "JanelaResolverQuestoes"
                  and tipo in (QEvent.Show, QEvent.Hide, QEvent.Close, QEvent.WindowStateChange)):
                if tipo == QEvent.Show:
                    self._pausar()  # antes do primeiro som da bateria
                QTimer.singleShot(0, self.sincronizar)
        except (RuntimeError, AttributeError):
            pass
        return False

    def _garantir_arquivo(self):
        try:
            if self._arquivo.is_file():
                if hashlib.sha256(self._arquivo.read_bytes()).hexdigest() == _B41_SHA256:
                    return True
            audio = zlib.decompress(base64.b85decode(_B41_AUDIO))
            if hashlib.sha256(audio).hexdigest() != _B41_SHA256:
                raise ValueError("integridade SHA-256 da trilha divergente")
            self._arquivo.parent.mkdir(parents=True, exist_ok=True)
            temporario = self._arquivo.with_name(
                self._arquivo.name + "." + str(os.getpid()) + ".tmp"
            )
            temporario.write_bytes(audio)
            os.replace(temporario, self._arquivo)
            return True
        except (OSError, ValueError, zlib.error) as exc:
            self._indisponivel("erro ao extrair trilha: " + str(exc))
            return False

    def _reproduzir(self):
        if self._em_execucao:
            return
        if not self._garantir_arquivo():
            return
        if self._backend == "qt" and self._efeito is not None:
            try:
                self._efeito.play()
                self._em_execucao = True
                return
            except (RuntimeError, OSError):
                self._backend = None
        if self._backend == "mci" and self._mci_aberto:
            comando = ("resume " + self._alias if self._mci_pausado
                       else "play " + self._alias)
            if self._mci_enviar(comando) is None:
                # Alguns drivers waveaudio nao implementam MCI_RESUME.
                if self._mci_enviar("play " + self._alias + " from 0") is None:
                    self._indisponivel("MCI nao conseguiu retomar a musica")
                    return
            self._mci_pausado = False
            self._em_execucao = True
            self._repetir.start()
            return
        if QSoundEffect is not None:
            try:
                if self._efeito is None:
                    self._efeito = QSoundEffect(self)
                    self._efeito.setSource(QUrl.fromLocalFile(str(self._arquivo)))
                    self._efeito.setLoopCount(QSoundEffect.Infinite)
                    self._efeito.setVolume(0.72)  # WAV entregue com nivel reduzido
                    self._efeito.statusChanged.connect(self._status_qt)
                if self._efeito.status() != QSoundEffect.Status.Error:
                    self._backend = "qt"
                    self._efeito.play()
                    self._em_execucao = True
                    QTimer.singleShot(1600, self._verificar_backend_qt)
                    return
            except (RuntimeError, OSError, AttributeError) as exc:
                self._backend = None
                self._log("QtMultimedia: " + str(exc))
        self._reproduzir_mci()

    def _status_qt(self):
        try:
            if (self._efeito is not None and
                    self._efeito.status() == QSoundEffect.Status.Error):
                self._backend = None
                self._em_execucao = False
                if self._pode_tocar():
                    self._reproduzir_mci()
        except (RuntimeError, AttributeError):
            pass

    def _verificar_backend_qt(self):
        if self._backend != "qt" or self._efeito is None or not self._pode_tocar():
            return
        try:
            if (self._efeito.status() == QSoundEffect.Status.Error
                    or (self._efeito.isLoaded() and not self._efeito.isPlaying())):
                self._efeito.stop()
                self._backend = None
                self._em_execucao = False
                self._reproduzir_mci()
        except (RuntimeError, AttributeError):
            pass

    def _mci_enviar(self, comando, resposta=False):
        buffer = ctypes.create_unicode_buffer(80) if resposta else None
        try:
            retorno = ctypes.windll.winmm.mciSendStringW(
                comando, buffer, len(buffer) if buffer is not None else 0, None
            )
            return buffer.value if retorno == 0 and buffer is not None else ("" if retorno == 0 else None)
        except (AttributeError, OSError):
            return None

    def _reproduzir_mci(self):
        if sys.platform != "win32":
            self._indisponivel("QtMultimedia nao disponivel")
            return
        if not self._mci_aberto:
            comando = ('open "' + str(self._arquivo) + '" type waveaudio alias ' + self._alias)
            if self._mci_enviar(comando) is None:
                self._indisponivel("nao foi possivel abrir o arquivo de audio via MCI")
                return
            self._mci_aberto = True
        # Som separado de PlaySound; nao interfere nas recompensas B38.
        self._backend = "mci"
        if self._mci_enviar("play " + self._alias + " from 0") is None:
            self._indisponivel("MCI nao conseguiu reproduzir")
            return
        self._em_execucao = True
        self._mci_pausado = False
        self._repetir.start()

    def _checar_loop_mci(self):
        if self._backend != "mci" or not self._pode_tocar() or not self._em_execucao:
            return
        estado = self._mci_enviar("status " + self._alias + " mode", resposta=True)
        if estado == "stopped":
            self._mci_enviar("play " + self._alias + " from 0")

    def _pausar(self):
        if self._backend == "qt" and self._efeito is not None:
            try:
                self._efeito.stop()
            except RuntimeError:
                pass
        elif self._backend == "mci" and self._mci_aberto and self._em_execucao:
            self._mci_enviar("pause " + self._alias)
            self._mci_pausado = True
            self._repetir.stop()
        self._em_execucao = False

    def _log(self, mensagem):
        if not self._avisou_falha:
            self._avisou_falha = True
            print("B41 musica ambiente:", mensagem, file=sys.stderr)

    def _indisponivel(self, mensagem):
        self._falha = True
        self._em_execucao = False
        self._repetir.stop()
        self._log(mensagem)
        for botao in (self._botao_cartoon, self._botao_normal):
            botao.setToolTip("A faixa ambiente nao pode ser reproduzida. " + mensagem)

    def finalizar(self):
        if self._encerrado:
            return
        self._encerrado = True
        self._repetir.stop()
        if self._efeito is not None:
            try:
                self._efeito.stop()
            except RuntimeError:
                pass
        if self._mci_aberto:
            self._mci_enviar("stop " + self._alias)
            self._mci_enviar("close " + self._alias)
            self._mci_aberto = False
        self._em_execucao = False
